('paris-window-pane-mirror-white', 'Paris Window Pane Mirror – White', 'Floor Mirrors', 30000, NULL, NULL, 'active', 3, 1, '24Ld052702', 'MH-PARIS-WHT', '', '200 cm high × 100 cm wide', 'New', false, '["images/products/paris-window-pane-mirror-white.jpg","images/products/paris-window-pane-mirror-pair.jpg"]'::jsonb, 'Bring the charm of a Parisian window into your home. The Paris is a 2-metre full-length mirror with a crisp white frame divided into 24 classic window panes, framing your room like a sunlit view. Fresh and coastal, it adds light, depth and character to living rooms, bedrooms and entryways. Hang it on the wall or lean it against it.', '["200 cm high × 100 cm wide","Window-pane design with a crisp white frame","Hang on the wall or lean against it","Also available in Black","Ships in a heavy-duty cardboard box with protective foam"]'::jsonb, 0),
('paris-window-pane-mirror-black', 'Paris Window Pane Mirror – Black', 'Floor Mirrors', 30000, NULL, NULL, 'active', 2, 1, '24Ld052702', 'MH-PARIS-BLK', '', '200 cm high × 100 cm wide', 'New', false, '["images/products/paris-window-pane-mirror-black.jpg","images/products/paris-window-pane-mirror-pair.jpg"]'::jsonb, 'Bring the charm of a Parisian window into your home. The Paris is a 2-metre full-length mirror with a classic black frame divided into 24 classic window panes, framing your room like a sunlit view. Bold and architectural, it adds light, depth and character to living rooms, bedrooms and entryways. Hang it on the wall or lean it against it.', '["200 cm high × 100 cm wide","Window-pane design with a classic black frame","Hang on the wall or lean against it","Also available in White","Ships in a heavy-duty cardboard box with protective foam"]'::jsonb, 1),
('cut-above-knife-mirror-black', 'Cut Above Knife Mirror – Black', 'Wall Mirrors', 25000, NULL, NULL, 'active', 4, 1, '24LD062402', 'MH-KNIFE-BLK', '', '200 cm high × 40 cm wide', 'New', false, '["images/products/cut-above-knife-mirror-black.jpg","images/products/cut-above-knife-mirror-black-venue.jpg"]'::jsonb, 'A cut above the rest. Shaped like an oversized chef''s knife, this 2-metre statement mirror pairs a sleek black handle, complete with polished rivet details, with a mirrored blade that reflects the room around it. Mount it on a feature wall or stand it freestanding, and watch it become the talking point of any restaurant, bar, café or modern home. Make your space stand out with a designer piece nobody will forget.', '["200 cm high × 40 cm wide","Unique knife-shaped design","Stylish black finish with rivet details on the handle","Mount on the wall or use freestanding","Perfect for restaurants and bars, cafés and commercial fit-outs, feature walls, modern homes and entertainment areas","Ships in a heavy-duty cardboard box with protective foam"]'::jsonb, 2),
('belle-beaded-mirror-silver', 'Belle Beaded Mirror – Silver', 'Floor Mirrors', 24000, NULL, NULL, 'active', 4, 1, '123D302-BIG', 'MH-BELLE-SLV', '', '190 cm high × 90 cm wide', 'New', false, '["images/products/belle-beaded-mirror-silver.jpg","images/products/belle-beaded-mirror-colours.jpg"]'::jsonb, 'Light-catching glamour from every angle. The Belle is a 190 cm full-length mirror framed by a wide border of bevelled mirror panels, edged inside and out with rows of polished silver beading. Mirror on mirror bounces light around the room for a look that''s fresh, bright and endlessly versatile, perfect for bedrooms, dressing rooms, living rooms and entryways. Hang it on the wall or lean it against it.', '["190 cm high × 90 cm wide","Bevelled mirror border with polished silver beaded trim","Hang on the wall or lean against it","Full-length statement mirror","Also available in Black and Gold","Ships in a heavy-duty cardboard box with protective foam"]'::jsonb, 3),
