('ribbed-amber-glassware-set', 'Ribbed Amber Glassware (Set of 4)', 'Tableware', 7900, NULL, NULL, 'archived', NULL, NULL, '', '', '', '', '', false, '[]'::jsonb, 'Four mouth-blown tumblers in warm amber glass with a fine vertical rib. Weighty in the hand and they stack neatly.', '["Set of 4, 300ml each","Mouth-blown soda-lime glass","Dishwasher safe on a gentle cycle"]'::jsonb, 1002),
('travertine-catch-all-tray', 'Travertine Catch-All Tray', 'Ceramics & Vases', 9500, NULL, NULL, 'archived', NULL, NULL, '', '', '', '', '', false, '[]'::jsonb, 'A shallow oval of honed travertine for keys, rings and small things by the door or bed.', '["24 × 12cm","Natural travertine, sealed","Felt pads underneath"]'::jsonb, 1003);
